answer:
1. Call by Value: Value is copied to formal arguments. Modifications inside function do not reflect on actual arguments.
2. Call by Reference: Address/reference of actual arguments is passed using reference operator (&). Modifications directly alter original variables.

Working Program:
#include <iostream>
using namespace std;
void swapByVal(int a, int b) {
    int temp = a; a = b; b = temp;
}
void swapByRef(int &a, int &b) {
    int temp = a; a = b; b = temp;
}
int main() {
    int x = 10, y = 20;
    swapByVal(x, y);
    cout << "After Call by Value: x=" << x << " y=" << y << endl; // 10, 20
    swapByRef(x, y);
    cout << "After Call by Reference: x=" << x << " y=" << y << endl; // 20, 10
    return 0;
}

